INSERT INTO review_findings (review_id, finding_number, severity, category, module, title, description, evidence, impact) VALUES
('ca9e914c-cce6-4db4-b3b1-29779d8e1837', 226, 'high', 'type_mismatch', 'skill', 'SkillSource missing ai-built variant that DB allows', 'DB skills_source_check: clawhub, local, generated, imported, ai-built. Gleam SkillSource: Clawhub, Local, Generated, Imported. Missing ai-built.', 'skill.gleam:16 SkillSource has 4 variants; DB CHECK has 5 values including ai-built', 'Decode fails for ai-built skills; INSERT with ai-built source from Gleam impossible'),
('ca9e914c-cce6-4db4-b3b1-29779d8e1837', 227, 'high', 'type_mismatch', 'task', 'TaskStatus missing FAKE_COMPLETE variant that DB allows', 'DB tasks_status_check: PENDING, RUNNING, COMPLETED, FAILED, FAKE_COMPLETE. Gleam TaskStatus: Pending, Running, Completed, Failed. Missing FAKE_COMPLETE.', 'task.gleam:9 TaskStatus has 4 variants; DB CHECK has 5 values including FAKE_COMPLETE', 'Decode fails for FAKE_COMPLETE tasks; cannot represent this status in Gleam'),
('ca9e914c-cce6-4db4-b3b1-29779d8e1837', 228, 'medium', 'type_mismatch', 'meeting', 'MeetingStatus has Pending but DB only allows active/completed/cancelled', 'DB meetings_status_check: active, completed, cancelled. Gleam MeetingStatus: Pending, Active, Completed, Cancelled. Pending not in DB.', 'meeting.gleam:10 MeetingStatus has Pending; DB CHECK has no pending value', 'INSERT with pending status will fail DB constraint; Gleam type allows invalid state'),
('ca9e914c-cce6-4db4-b3b1-29779d8e1837', 229, 'high', 'type_mismatch', 'issue_types', 'IssueStatus missing acknowledged/wont_fix/duplicate; has Closed which DB doesnt have', 'DB issues_status_check: open, acknowledged, in_progress, resolved, wont_fix, duplicate. Gleam IssueStatus: Open, InProgress, Resolved, Closed. Missing 3, extra 1.', 'issue_types.gleam:13 string_to_status() maps closed->Closed but DB has no closed; acknowledged/wont_fix/duplicate cause Error', 'Decode fails for acknowledged/wont_fix/duplicate issues; Closed maps to non-existent DB status; INSERT with Closed fails'),
('ca9e914c-cce6-4db4-b3b1-29779d8e1837', 230, 'medium', 'type_mismatch', 'issue_types', 'IssueType missing proposal which DB allows', 'DB issues_issue_type_check: bug, inconsistency, feature, improvement, question, debt, proposal. Gleam IssueType: Bug, Inconsistency, Feature, Improvement, Question, Debt. Missing proposal.', 'issue_types.gleam:20 string_to_type() has no proposal case', 'Decode fails for proposal-type issues; cannot create proposal issues from Gleam');
